"""Versioned prompt registry backed by prompts/ files."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PROMPTS_DIR = ROOT / "prompts"

DIAGRAM_PROMPT_MAP = {
    "class": "tech_spec_to_class",
    "object": "tech_spec_to_object",
    "component": "tech_spec_to_component",
    "package": "tech_spec_to_package",
}


@dataclass(frozen=True)
class PromptRef:
    name: str
    version: str
    path: Path
    body: str


def list_prompt_files() -> list[Path]:
    if not PROMPTS_DIR.is_dir():
        return []
    return sorted(PROMPTS_DIR.glob("*.v*.txt"))


def load_prompt(name: str, version: str = "v1") -> PromptRef:
    path = PROMPTS_DIR / f"{name}.{version}.txt"
    if not path.is_file():
        # fallback: any matching name.version*
        matches = list(PROMPTS_DIR.glob(f"{name}.{version}*.txt"))
        if not matches:
            raise FileNotFoundError(f"Prompt not found: {name} {version} ({path})")
        path = matches[0]
    body = path.read_text(encoding="utf-8")
    return PromptRef(name=name, version=version, path=path, body=body)


def render_prompt(name: str, version: str = "v1", **kwargs: str) -> tuple[PromptRef, str]:
    ref = load_prompt(name, version)
    return ref, ref.body.format(**kwargs)


def diagram_prompt_name(diagram_type: str) -> str:
    if diagram_type not in DIAGRAM_PROMPT_MAP:
        raise ValueError(f"Unknown diagram type: {diagram_type}")
    return DIAGRAM_PROMPT_MAP[diagram_type]

"""Build chat/vision providers from application settings."""

from __future__ import annotations

from pathlib import Path

from uml_pipeline.llm_client import LLMClient

from app.providers.mock_provider import MockProvider
from app.settings import Settings, get_settings


class OpenAIProvider:
    name = "openai"

    def __init__(self, model: str, base_url: str | None = None, api_key: str | None = None):
        self.model = model
        self._client = LLMClient(model=model, provider="openai", base_url=base_url, api_key=api_key)

    def chat(self, system: str, user: str, temperature: float = 0.7) -> str:
        return self._client.chat(system, user, temperature)

    def vision_score(self, image_path: Path, prompt: str) -> int:
        return self._client.vision_score(image_path, prompt)


class OllamaProvider:
    name = "ollama"

    def __init__(self, model: str):
        self.model = model
        self._client = LLMClient(model=model, provider="ollama")

    def chat(self, system: str, user: str, temperature: float = 0.7) -> str:
        return self._client.chat(system, user, temperature)

    def vision_score(self, image_path: Path, prompt: str) -> int:
        return self._client.vision_score(image_path, prompt)


def build_chat_provider(settings: Settings | None = None, model: str | None = None):
    settings = settings or get_settings()
    model = model or settings.spec_model
    if settings.mock_providers:
        return MockProvider()
    if settings.use_ollama:
        return OllamaProvider(model)
    return OpenAIProvider(model, base_url=settings.openai_base_url, api_key=settings.openai_api_key)


def build_code_provider(settings: Settings | None = None):
    settings = settings or get_settings()
    return build_chat_provider(settings, model=settings.code_model)


def build_vlm_providers(settings: Settings | None = None) -> dict[str, object]:
    """Map paper weight keys -> provider instances (or unavailable markers)."""
    settings = settings or get_settings()
    keys = list(settings.vlm_weight_map.keys())
    models = settings.vlm_model_list
    providers: dict[str, object] = {}
    for i, key in enumerate(keys):
        model = models[i] if i < len(models) else models[-1] if models else "mock-vlm"
        if settings.mock_providers:
            providers[key] = MockProvider()
        elif settings.use_ollama:
            providers[key] = OllamaProvider(model)
        else:
            providers[key] = OpenAIProvider(
                model, base_url=settings.openai_base_url, api_key=settings.openai_api_key
            )
        getattr(providers[key], "model", None)
        if not hasattr(providers[key], "model"):
            providers[key].model = model  # type: ignore[attr-defined]
        else:
            # ensure model attribute for logging
            try:
                providers[key].model = model  # type: ignore[attr-defined]
            except Exception:
                pass
    return providers

"""PlantUML syntax validation and package semantic guards."""

from __future__ import annotations

import re
from dataclasses import dataclass, field


@dataclass
class ValidationResult:
    ok: bool
    messages: list[str] = field(default_factory=list)

    def merge(self, other: "ValidationResult") -> "ValidationResult":
        return ValidationResult(ok=self.ok and other.ok, messages=self.messages + other.messages)


def ensure_plantuml_bounds(code: str) -> str:
    text = code.strip()
    # Strip markdown fences
    text = re.sub(r"^```(?:plantuml)?\s*", "", text, flags=re.I)
    text = re.sub(r"\s*```$", "", text)
    if "@startuml" not in text.lower():
        text = f"@startuml\n{text}\n@enduml"
    elif "@enduml" not in text.lower():
        text = text + "\n@enduml"
    # Keep only first diagram block
    m = re.search(r"@startuml.*?@enduml", text, flags=re.I | re.S)
    return m.group(0) if m else text


def validate_basic_syntax(code: str) -> ValidationResult:
    msgs: list[str] = []
    if "@startuml" not in code.lower():
        msgs.append("Missing @startuml")
    if "@enduml" not in code.lower():
        msgs.append("Missing @enduml")
    if code.lower().count("@startuml") > 1:
        msgs.append("Multiple @startuml blocks")
    # Unbalanced braces
    if code.count("{") != code.count("}"):
        msgs.append("Unbalanced curly braces")
    return ValidationResult(ok=not msgs, messages=msgs)


def validate_package_semantics(code: str) -> ValidationResult:
    """Guards for the hardest failure mode: package diagrams."""
    msgs: list[str] = []
    lines = code.splitlines()

    # Self-referential dependencies
    for line in lines:
        m = re.search(r"^\s*([A-Za-z_][\w.]*)\s+(\.\.>|->|-->)\s*\1\b", line)
        if m:
            msgs.append(f"Self-referential dependency: {line.strip()}")

    # Dotted names used as peer packages without nesting
    # Flag patterns like: package com.app.core (suggests nesting confusion)
    dotted_pkgs = re.findall(r"package\s+([A-Za-z0-9]+(?:\.[A-Za-z0-9]+)+)", code)
    if len(dotted_pkgs) >= 2:
        # If many dotted peer packages and no nested package { blocks, warn
        nested = bool(re.search(r"package\s+\w+\s*\{", code))
        if not nested:
            msgs.append(
                "Multiple dotted package names without nesting; "
                "prefer nested package { } for containment"
            )

    # Contained packages declared again as top-level peers (simple heuristic)
    top_level = re.findall(r"(?m)^package\s+(\w+)", code)
    if len(top_level) != len(set(top_level)):
        msgs.append("Duplicate package names at declaration sites")

    # Confusion: using +-- containment connector incorrectly between same package
    for line in lines:
        if re.search(r"^\s*(\w+)\s+\+--\s*\1\b", line):
            msgs.append(f"Invalid self-containment: {line.strip()}")

    return ValidationResult(ok=not msgs, messages=msgs)


def validate_object_syntax(code: str) -> ValidationResult:
    msgs: list[str] = []
    # Common failure: object Name without :Type and with invalid attribute block
    if "object " in code.lower() and not re.search(r"object\s+\w+\s*:\s*\w+", code, re.I):
        if re.search(r"object\s+\w+\s*\{", code, re.I):
            msgs.append("Object instances should use name:Type syntax")
    return ValidationResult(ok=not msgs, messages=msgs)


def validate_component_syntax(code: str) -> ValidationResult:
    msgs: list[str] = []
    # Broken interface: () without name
    if re.search(r"\(\)\s*$", code, re.M):
        msgs.append("Empty component interface notation")
    return ValidationResult(ok=not msgs, messages=msgs)


def validate_diagram(code: str, diagram_type: str) -> ValidationResult:
    code = ensure_plantuml_bounds(code)
    result = validate_basic_syntax(code)
    if diagram_type == "package":
        result = result.merge(validate_package_semantics(code))
    elif diagram_type == "object":
        result = result.merge(validate_object_syntax(code))
    elif diagram_type == "component":
        result = result.merge(validate_component_syntax(code))
    return result

"""Paper-aligned composite scoring helpers."""

from __future__ import annotations

from uml_pipeline.scoring import weighted_composite as _weighted_composite


def paper_composite(
    scores: dict[str, float | int | None],
    weights: dict[str, float],
) -> float:
    """
    valid_scores = [(score_i, weight_i) for each model where score_i > 0]
    final_score = 0 if empty else sum(score_i * weight_i) / sum(weight_i)
    """
    value = _weighted_composite(scores, weights)
    return 0.0 if value is None else float(value)


def formula_snapshot(
    scores: dict[str, float | int | None],
    weights: dict[str, float],
    final: float,
) -> str:
    parts = []
    for k, s in scores.items():
        if s is None:
            continue
        parts.append(f"{k}={s}(w={weights.get(k, 0)})")
    return "final=" + f"{final:.4f}" + " | " + ", ".join(parts)

from __future__ import annotations

import shutil
import subprocess

from fastapi import APIRouter, Depends, Query
from fastapi.responses import Response
from sqlmodel import Session

from app.db import get_session
from app.schemas import AnalyticsSummary, HealthResponse
from app.services.analytics import analytics_summary, export_dataset, score_distributions
from app.settings import get_settings

router = APIRouter(prefix="/api", tags=["analytics"])


@router.get("/analytics/summary", response_model=AnalyticsSummary)
def summary(session: Session = Depends(get_session)):
    data = analytics_summary(session)
    return AnalyticsSummary(**data)


@router.get("/analytics/distributions")
def distributions(session: Session = Depends(get_session)):
    return score_distributions(session)


@router.get("/export/dataset")
def export(fmt: str = Query(default="jsonl", pattern="^(jsonl|csv|parquet)$"), session: Session = Depends(get_session)):
    body, media, filename = export_dataset(session, fmt=fmt)
    return Response(
        content=body,
        media_type=media,
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@router.get("/settings/health", response_model=HealthResponse)
def health(session: Session = Depends(get_session)):
    settings = get_settings()
    messages: list[str] = []
    database_ok = True
    try:
        session.connection()
    except Exception as exc:
        database_ok = False
        messages.append(f"Database error: {exc}")

    jar_ok = settings.plantuml_jar.is_file()
    if not jar_ok:
        messages.append(f"PlantUML jar missing at {settings.plantuml_jar} (will auto-download on first render)")

    java_ok = shutil.which("java") is not None
    if not java_ok:
        messages.append("Java JDK not found on PATH — rendering will fail until installed")
    else:
        try:
            subprocess.run(["java", "-version"], capture_output=True, timeout=10, check=False)
        except Exception as exc:
            java_ok = False
            messages.append(f"Java check failed: {exc}")

    if settings.mock_providers:
        messages.append("MOCK_PROVIDERS=true — using deterministic mock LLM/VLM responses")

    status = "ok" if database_ok else "degraded"
    if not java_ok:
        status = "degraded"

    return HealthResponse(
        status=status,
        provider=settings.provider_name,
        mock_providers=settings.mock_providers,
        database_ok=database_ok,
        plantuml_jar_present=jar_ok,
        java_available=java_ok,
        messages=messages,
    )

"""Unit tests for paper-aligned composite scoring."""

from app.services.scoring import formula_snapshot, paper_composite


def test_composite_weighted_average():
    scores = {"qwen25vl3b": 6, "llama32vl11b": 4, "aya_vision_8b": 2}
    weights = {"qwen25vl3b": 53.1, "llama32vl11b": 50.7, "aya_vision_8b": 39.9}
    expected = (6 * 53.1 + 4 * 50.7 + 2 * 39.9) / (53.1 + 50.7 + 39.9)
    assert abs(paper_composite(scores, weights) - expected) < 1e-9


def test_composite_ignores_zero_and_none():
    scores = {"qwen25vl3b": 0, "llama32vl11b": None, "aya_vision_8b": 5}
    weights = {"qwen25vl3b": 53.1, "llama32vl11b": 50.7, "aya_vision_8b": 39.9}
    assert paper_composite(scores, weights) == 5.0


def test_composite_all_invalid_is_zero():
    scores = {"qwen25vl3b": 0, "llama32vl11b": 0, "aya_vision_8b": None}
    weights = {"qwen25vl3b": 53.1, "llama32vl11b": 50.7, "aya_vision_8b": 39.9}
    assert paper_composite(scores, weights) == 0.0


def test_formula_snapshot_contains_final():
    scores = {"qwen25vl3b": 3}
    weights = {"qwen25vl3b": 53.1}
    snap = formula_snapshot(scores, weights, 3.0)
    assert "final=3.0000" in snap
    assert "qwen25vl3b=3" in snap

